def drive(me, enemy, arena):
    # steer toward enemy, avoid bubble wall
    try:
        b = bearing_to(enemy.x, enemy.y)
        d = distance_to(enemy.x, enemy.y)
        rc = (me.x * me.x + me.y * me.y) ** 0.5
        left = 1.0
        right = 1.0
        if rc > 4.8:
            # head toward centre
            bc = bearing_to(0.0, 0.0)
            if bc > 5:
                left, right = -0.6, 0.6
            elif bc < -5:
                left, right = 0.6, -0.6
        elif d > 0.5:
            if b > 8:
                left, right = 0.4, 1.0
            elif b < -8:
                left, right = 1.0, 0.4
            else:
                left, right = 1.0, 1.0
        else:
            # close in: keep pushing forward
            if b > 20:
                left, right = -0.3, 0.8
            elif b < -20:
                left, right = 0.8, -0.3
            else:
                left, right = 0.9, 0.9
        # if flipped on side or can't drive, try nothing from drive
        if me.on_side:
            return (0.0, 0.0)
        return (left, right)
    except Exception:
        return (0.0, 0.0)


