def drive(me, enemy, arena):
    try:
        if not me.can_drive:
            return (0, 0)
        b = bearing_to(enemy.x, enemy.y)
        d = distance_to(enemy.x, enemy.y)
        if d < 0.01:
            return (0, 0)
        if abs(b) > 120:
            if b > 0:
                return (-1, 1)
            return (1, -1)
        base = 1 if d > 0.8 else 0.75
        t = b / 70
        if t > 1:
            t = 1
        elif t < -1:
            t = -1
        l = base - t
        r = base + t
        if l > 1:
            l = 1
        elif l < -1:
            l = -1
        if r > 1:
            r = 1
        elif r < -1:
            r = -1
        return (l, r)
    except Exception:
        return (0, 0)

