def lim(x, a, b):
    if x < a:
        return a
    if x > b:
        return b
    return x

def drive(me, enemy, arena):
    try:
        if not me.can_drive:
            return (0, 0)
        bat = me.battery_wh
        if bat < 35:
            return (0, 0)

        r = hypot(me.x, me.y)
        if r > 5.7:
            b = bearing_to(0, 0)
            if abs(b) > 110:
                if b > 0:
                    return (-1, 1)
                return (1, -1)
            t = lim(b / 65.0, -1.0, 1.0)
            base = 0.85 if bat > 150 else 0.6
            return (lim(base - t, -1.0, 1.0), lim(base + t, -1.0, 1.0))

        b = bearing_to(enemy.x, enemy.y)
        d = distance_to(enemy.x, enemy.y)
        if d < 0.05:
            return (0, 0)

        if abs(b) > 125:
            if b > 0:
                return (-1, 1)
            return (1, -1)

        if bat < 150:
            base = 0.65
        elif bat < 300:
            base = 0.8
        elif d < 0.55:
            base = 0.7
        elif d < 1.2:
            base = 0.9
        else:
            base = 1.0

        t = lim(b / 60.0, -1.0, 1.0)
        return (lim(base - t, -1.0, 1.0), lim(base + t, -1.0, 1.0))
    except Exception:
        return (0, 0)

